 verify_csrf();if(!in_array($role,['system_admin','sub_admin','admin'],true)){http_response_code(403);exit('You cannot check director SMS delivery.');}
 try{$pdo=db();$logId=(int)($_POST['log_id']??0);$sql="SELECT l.id,l.actor_id,l.status,l.provider_message_id FROM sms_delivery_logs l WHERE l.id=? AND l.status IN ('failed','accepted') AND NOT EXISTS(SELECT 1 FROM sms_delivery_logs newer WHERE newer.director_user_id=l.director_user_id AND newer.id>l.id)";if($role==='admin')$sql.=' AND l.actor_id=?';$q=$pdo->prepare($sql);$role==='admin'?$q->execute([$logId,$uid]):$q->execute([$logId]);$attempt=$q->fetch();if(!$attempt)throw new DomainException('This is not the latest SMS attempt. Refresh SMS history.');
  if(!empty($attempt['provider_message_id'])){$check=check_director_sms_delivery((string)$attempt['provider_message_id']);$delivery=$check['delivery_status']??null;$diagnostic=$check['diagnostic'];if(!$check['ok'])throw new DomainException($diagnostic);}
  else{$delivery='submission_failed';$diagnostic='The provider did not accept the SMS request, so no message ID was issued. Resending is available.';}
  $update=$pdo->prepare('UPDATE sms_delivery_logs SET delivery_status=?,status_checked_at=NOW(),status_check_diagnostic=? WHERE id=?');$update->execute([$delivery,$diagnostic,$logId]);$audit=$pdo->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$audit->execute([$uid,'check_director_sms_delivery','sms_delivery_log',$logId,json_encode(['delivery_status'=>$delivery])]);header('Location: schools.php#sms-history');exit;
 }catch(DomainException $ex){$error=$ex->getMessage();}catch(Throwable $ex){$error='SMS delivery status could not be checked. Apply the latest SMS delivery status migration and try again.';}
}
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='retry_sms'){
 verify_csrf();if(!in_array($role,['system_admin','sub_admin','admin'],true)){http_response_code(403);exit('You cannot retry director SMS delivery.');}
 try{$pdo=db();$logId=(int)($_POST['log_id']??0);$sql="SELECT l.id,l.school_id,l.actor_id,l.director_user_id,l.delivery_status,d.name,d.phone,d.email,d.username FROM sms_delivery_logs l JOIN users d ON d.id=l.director_user_id WHERE l.id=? AND l.status IN ('failed','accepted') AND d.role='director' AND d.status='active' AND l.delivery_status IN ('undelivered','failed','denied','rejected','expired','submission_failed') AND NOT EXISTS(SELECT 1 FROM sms_delivery_logs newer WHERE newer.director_user_id=l.director_user_id AND newer.id>l.id)";if($role==='admin')$sql.=' AND l.actor_id=?';$q=$pdo->prepare($sql);$role==='admin'?$q->execute([$logId,$uid]):$q->execute([$logId]);$failed=$q->fetch();if(!$failed)throw new DomainException('Check the latest message status first. Retry is available only after delivery is confirmed failed.');if(trim((string)$failed['phone'])==='')throw new DomainException('The director has no phone number. Update the account before retrying.');
  $chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';$newPassword='';for($i=0;$i<6;$i++)$newPassword.=$chars[random_int(0,strlen($chars)-1)];$pdo->beginTransaction();$update=$pdo->prepare("UPDATE users SET password_hash=?,must_change_password=1 WHERE id=? AND status='active'");$update->execute([password_hash($newPassword,PASSWORD_DEFAULT),$failed['director_user_id']]);if($update->rowCount()!==1)throw new DomainException('The director account changed. Refresh and try again.');$pdo->commit();
  $smsResult=send_director_password_sms($failed['phone'],$failed['name'],$newPassword);try{$log=$pdo->prepare('INSERT INTO sms_delivery_logs(school_id,director_user_id,actor_id,recipient,endpoint,http_status,status,provider_message_id,diagnostic) VALUES(?,?,?,?,?,?,?,?,?)');$log->execute([$failed['school_id'],$failed['director_user_id'],$uid,$smsResult['recipient']??director_sms_phone($failed['phone'])??$failed['phone'],$smsResult['endpoint'],$smsResult['http_status'],$smsResult['accepted']?'accepted':'failed',$smsResult['message_id'],$smsResult['diagnostic']]);$smsLogId=(int)$pdo->lastInsertId();$audit=$pdo->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$audit->execute([$uid,'retry_director_sms','user',$failed['director_user_id'],json_encode(['prior_sms_log_id'=>$logId,'sms_log_id'=>$smsLogId])]);}catch(Throwable $logError){$smsResult['diagnostic'].=' The SMS result could not be recorded; check the database migration.';}
  $_SESSION['created_school_director_credentials']=['name'=>$failed['name'],'identifier'=>$failed['email']?:$failed['username'],'password'=>$smsResult['accepted']?null:$newPassword,'sms_sent'=>$smsResult['accepted'],'sms_retry'=>true,'sms_diagnostic'=>$smsResult['diagnostic']];header('Location: schools.php#sms-history');exit;
 }catch(DomainException $ex){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error=$ex->getMessage();}catch(Throwable $ex){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error='SMS retry could not be completed. Check the SMS history and database configuration.';}
