 $name=trim((string)($_POST['name']??''));$location=trim((string)($_POST['location']??''));$phone=trim((string)($_POST['phone']??''));$newDirector=$role!=='director'&&($_POST['director_id']??'')==='new';$directorId=$role==='director'?$uid:($newDirector?0:(int)($_POST['director_id']??0));
 $directorName=trim((string)($_POST['director_name']??''));$directorIdentifier=strtolower(trim((string)($_POST['director_identifier']??'')));$directorPhone=trim((string)($_POST['director_phone']??''));$directorEmail=filter_var($directorIdentifier,FILTER_VALIDATE_EMAIL)?$directorIdentifier:null;$directorUsername=$directorEmail?null:$directorIdentifier;
 if($name===''||strlen($name)>180||strlen($phone)>30)$error='Enter a school name (up to 180 characters).';
 elseif($role!=='director'&&!$newDirector&&!$directorId)$error='Choose the director who owns this school.';
 elseif($newDirector&&($directorName===''||strlen($directorName)>180||($directorEmail===null&&!preg_match('/^[a-z0-9._-]{3,60}$/',$directorUsername))||$directorPhone===''||strlen($directorPhone)>30))$error='Enter the director name, a valid email or username, and phone number.';
 else{try{$pdo=db();$pdo->beginTransaction();$tempPassword=null;
  if($newDirector){$dupe=$pdo->prepare('SELECT id FROM users WHERE email=? OR username=? LIMIT 1');$dupe->execute([$directorIdentifier,$directorIdentifier]);if($dupe->fetch())throw new DomainException('That director sign-in ID is already in use.');$passwordChars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';$tempPassword='';for($i=0;$i<6;$i++)$tempPassword.=$passwordChars[random_int(0,strlen($passwordChars)-1)];$q=$pdo->prepare('INSERT INTO users(name,phone,email,username,password_hash,role,must_change_password) VALUES(?,?,?,?,?,?,1)');$q->execute([$directorName,$directorPhone,$directorEmail,$directorUsername,password_hash($tempPassword,PASSWORD_DEFAULT),'director']);$directorId=(int)$pdo->lastInsertId();}
