  $q=$pdo->prepare("INSERT INTO schools (name,location,phone,status,created_by) VALUES (?,?,?,'active',?)");$q->execute([$name,$location?:null,$phone?:null,$uid]);$schoolId=(int)$pdo->lastInsertId();$m=$pdo->prepare("INSERT INTO school_memberships (school_id,user_id,scope) VALUES (?,?,'manager')");$m->execute([$schoolId,$directorId]);if($role!=='director')$m->execute([$schoolId,$uid]);
  if($newDirector){$a=$pdo->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$a->execute([$uid,'create','user',$directorId,json_encode(['role'=>'director','school_id'=>$schoolId])]);}
  $a=$pdo->prepare('INSERT INTO audit_logs (actor_id,action,entity_type,entity_id,details) VALUES (?,?,?,?,?)');$a->execute([$uid,'create','school',$schoolId,json_encode(['name'=>$name,'director_id'=>$directorId,'director_created'=>$newDirector])]);$pdo->commit();if($newDirector){$smsResult=send_director_password_sms($directorPhone,$directorName,$tempPassword);try{$log=$pdo->prepare('INSERT INTO sms_delivery_logs(school_id,director_user_id,actor_id,recipient,endpoint,http_status,status,provider_message_id,diagnostic) VALUES(?,?,?,?,?,?,?,?,?)');$log->execute([$schoolId,$directorId,$uid,$smsResult['recipient']??director_sms_phone($directorPhone)??$directorPhone,$smsResult['endpoint'], $smsResult['http_status'],$smsResult['accepted']?'accepted':'failed',$smsResult['message_id'],$smsResult['diagnostic']]);}catch(Throwable $logError){$smsResult['diagnostic'].=' Delivery log could not be saved; apply the SMS log database migration.';}$_SESSION['created_school_director_credentials']=['name'=>$directorName,'identifier'=>$directorIdentifier,'password'=>$smsResult['accepted']?null:$tempPassword,'sms_sent'=>$smsResult['accepted'],'sms_diagnostic'=>$smsResult['diagnostic']];}header('Location: schools.php?saved=1');exit;
 }catch(DomainException $ex){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error=$ex->getMessage();}catch(Throwable $ex){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error='School could not be saved. Verify database/schema.sql is up to date.';}}
}
$schools=[];$directors=[];$smsLogs=[];$loadError='';try{$pdo=db();if($canAdd&&$role!=='director')$directors=$pdo->query("SELECT id,name,email,username,phone FROM users WHERE role='director' AND status='active' ORDER BY name")->fetchAll();if(in_array($role,['system_admin','sub_admin','admin'],true)){$sql="SELECT s.*,creator.name created_by_name,(SELECT u.name FROM school_memberships sm JOIN users u ON u.id=sm.user_id WHERE sm.school_id=s.id AND sm.scope='manager' AND u.role='director' ORDER BY sm.created_at LIMIT 1) director,(SELECT COUNT(*) FROM pupils p WHERE p.school_id=s.id AND p.status='active') pupil_count FROM schools s LEFT JOIN users creator ON creator.id=s.created_by";if($role==='admin'){$sql.=" JOIN school_memberships access ON access.school_id=s.id AND access.user_id=$uid";}$sql.=' ORDER BY s.created_at DESC';$schools=$pdo->query($sql)->fetchAll();}else{$q=$pdo->prepare("SELECT s.*,creator.name created_by_name,(SELECT u.name FROM school_memberships sm JOIN users u ON u.id=sm.user_id WHERE sm.school_id=s.id AND sm.scope='manager' AND u.role='director' ORDER BY sm.created_at LIMIT 1) director,(SELECT COUNT(*) FROM pupils p WHERE p.school_id=s.id AND p.status='active') pupil_count FROM schools s JOIN school_memberships m ON m.school_id=s.id LEFT JOIN users creator ON creator.id=s.created_by WHERE m.user_id=? ORDER BY s.created_at DESC");$q->execute([$uid]);$schools=$q->fetchAll();}}catch(Throwable $ex){$loadError='Schools are not available. Apply the latest database schema.';}if(in_array($role,['system_admin','sub_admin','admin'],true)){try{$logSql="SELECT l.*,d.name director_name,d.phone director_phone,d.status director_status,s.name school_name,a.name actor_name,NOT EXISTS(SELECT 1 FROM sms_delivery_logs newer WHERE newer.director_user_id=l.director_user_id AND newer.id>l.id) is_latest_attempt FROM sms_delivery_logs l LEFT JOIN users d ON d.id=l.director_user_id LEFT JOIN schools s ON s.id=l.school_id LEFT JOIN users a ON a.id=l.actor_id";if($role==='admin'){$logSql.=' WHERE l.actor_id=?';$logQuery=$pdo->prepare($logSql.' ORDER BY l.id DESC LIMIT 30');$logQuery->execute([$uid]);}else{$logQuery=$pdo->query($logSql.' ORDER BY l.id DESC LIMIT 30');}$smsLogs=$logQuery->fetchAll();}catch(Throwable $ex){$smsLogLoadError='SMS history is unavailable. Apply database/migrations/20261030_sms_delivery_logs.sql.';}}
$saved=isset($_GET['saved']);$directorCredentials=$_SESSION['created_school_director_credentials']??null;unset($_SESSION['created_school_director_credentials']);?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Schools · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script></head><body><div class="app-shell"><?php require __DIR__ . "/sidebar.php"; ?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Workspace <span>/</span> Schools</div><?php if(in_array($_SESSION['role']??'', ['system_admin','sub_admin'],true)):$pendingEditCount=pending_school_edit_request_count();?><a class="notification-bell" href="requests.php#requested" aria-label="<?=$pendingEditCount?> pending edit requests" title="<?=$pendingEditCount?> pending edit requests"><span aria-hidden="true">🔔</span><?php if($pendingEditCount):?><span class="notification-badge"><?=$pendingEditCount>99?'99+':$pendingEditCount?></span><?php endif;?></a><?php endif;?><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e($_SESSION['name'])?></div></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">SCHOOL NETWORK</div><h1>Schools</h1><p class="muted">Manage school records within your access.</p></div></section><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><?php if($saved):?><div class="notice success" role="status">School added and linked to its director.</div><?php endif;?><?php if($directorCredentials):?><div class="notice <?=!empty($directorCredentials['sms_sent'])?'success':'error'?> director-credentials" role="status"><strong><?=!empty($directorCredentials['sms_retry'])?'SMS retry for '.e($directorCredentials['name']):'Director account created for '.e($directorCredentials['name'])?>.</strong><br>Sign-in ID: <strong><?=e($directorCredentials['identifier'])?></strong> · <?php if(!empty($directorCredentials['sms_sent'])):?>SMS request accepted by the provider. Delivery to the handset is not confirmed here; the director must change the password after signing in.<?php else:?>SMS was not accepted by the provider (<?=e($directorCredentials['sms_diagnostic']??'no provider detail available')?>). Share this temporary password securely: <strong id="school-temp-pass"><?=e($directorCredentials['password'])?></strong><?php endif;?></div><?php endif;?><?php if($loadError):?><div class="notice error" role="alert"><?=e($loadError)?></div><?php endif;?><?php if(!empty($smsLogLoadError)):?><div class="notice error" role="alert"><?=e($smsLogLoadError)?></div><?php endif;?><?php if(in_array($role,['system_admin','sub_admin','admin'],true)):?><section class="content-section" id="sms-history"><div class="section-heading"><div><div class="eyebrow">DELIVERY DIAGNOSTICS</div><h2>Director SMS history</h2><p class="muted">The log stores provider results and diagnostics, never the password or SMS body.</p></div><span class="count-pill"><?=count($smsLogs)?> recent attempts</span></div><?php if(!$smsLogs):?><div class="empty-state"><h3>No director SMS attempts recorded</h3><p>New director registration attempts will appear here.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Time</th><th>School / director</th><th>Recipient</th><th>Provider details</th><th>Action</th></tr></thead><tbody><?php foreach($smsLogs as $smsLog):?><tr><td><?=e(date('j M Y H:i',strtotime($smsLog['created_at'])))?></td><td><?=e($smsLog['school_name']?:'School removed')?> / <?=e($smsLog['director_name']?:'Account removed')?></td><td><?=e($smsLog['recipient'])?></td><td><?=e(director_sms_provider_message($smsLog['diagnostic']?:$smsLog['provider_message_id']))?><?php if(!empty($smsLog['status_check_diagnostic'])):?><br><small><?=e($smsLog['status_check_diagnostic'])?><?=!empty($smsLog['status_checked_at'])?' - checked '.e(date('j M Y H:i',strtotime($smsLog['status_checked_at']))):''?></small><?php endif;?></td><td><?php if(in_array($smsLog['status'],['failed','accepted'],true)&&!empty($smsLog['is_latest_attempt'])&&$smsLog['director_status']==='active'&&$smsLog['director_phone']&&$role!=='director'):$delivery=strtolower((string)($smsLog['delivery_status']??''));$retryable=in_array($delivery,['undelivered','failed','denied','rejected','expired','submission_failed'],true);$delivered=in_array($delivery,['delivered','success','successful'],true);if($retryable):?><form method="post" onsubmit="return confirm('Retrying replaces the director temporary password with a new six-character password. Continue?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="retry_sms"><input type="hidden" name="log_id" value="<?=$smsLog['id']?>"><button class="button" type="submit">Retry / Resend</button></form><?php elseif($delivered):?><span class="status-pill accepted">Delivered</span><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="check_sms_status"><input type="hidden" name="log_id" value="<?=$smsLog['id']?>"><button class="button" type="submit">Recheck status</button></form><?php endif;?><?php elseif(in_array($smsLog['status'],['failed','accepted'],true)&&!empty($smsLog['is_latest_attempt'])):?>Account or phone needs updating<?php else:?>-<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endif;?><?php if($canAdd):?><section class="note-create"><div class="section-heading"><div><div class="eyebrow">REGISTER</div><h2>Add a school</h2></div></div><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div><label for="school-name">School name</label><input id="school-name" name="name" maxlength="180" required></div><div><label for="location">Location</label><input id="location" name="location" maxlength="180"></div><div><label for="school-phone">School phone</label><input id="school-phone" name="phone" type="tel" maxlength="30" autocomplete="tel"></div><?php if($role!=='director'):?><div><label for="director">School director</label><select id="director" name="director_id" required><option value="">Choose director</option><?php foreach($directors as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?> · <?=e($d['email']?:'username')?><?=($d['phone']?' · '.e($d['phone']):'') ?></option><?php endforeach;?><option value="new">Add a new director</option></select></div><div class="new-director-fields" id="new-director-fields" hidden><div class="eyebrow">NEW DIRECTOR ACCOUNT</div><p class="muted">Create the director sign-in now. The account will be linked to this school automatically.</p><div class="form-grid"><div><label for="director-name">Director name</label><input id="director-name" name="director_name" maxlength="180"></div><div><label for="director-identifier">Email or username</label><input id="director-identifier" name="director_identifier" maxlength="190" autocomplete="username"></div><div><label for="director-phone">Director phone</label><input id="director-phone" name="director_phone" type="tel" maxlength="30"></div></div></div><?php endif;?></div><button class="button primary" type="submit">Save school</button></form></section><?php endif;?><section class="content-section"><div class="section-heading"><div><div class="eyebrow">REGISTERED</div><h2>School records</h2></div><span class="count-pill"><?=count($schools)?> schools</span></div><?php if(!$schools):?><div class="empty-state"><span class="empty-icon">▦</span><h3>No schools in your access yet</h3><p>School records appear when a director registers a school or shares access with you.</p></div><?php else:?><div class="table-wrap<?= $role==='headteacher' ? ' hide-director' : '' ?>"><table><thead><tr><th>School</th><th>Location</th><th>Phone</th><?php if($role==='system_admin'||$role==='sub_admin'||$role==='admin'):?><th>Pupils</th><th>Created by</th><th>Created date</th><?php endif;?><th>Director</th><th>Status</th><?php if(in_array($role,['system_admin','sub_admin','admin'],true)):?><th>Actions</th><?php endif;?></tr></thead><tbody><?php foreach($schools as $s):?><tr><td class="school-cell"><?=e($s['name'])?></td><td><?=e($s['location']?:'—')?></td><td><?=e($s['phone']?:'—')?></td><?php if(in_array($role,['system_admin','sub_admin','admin'],true)):?><td><?=number_format((int)$s['pupil_count'])?></td><td><?=e($s['created_by_name']?:'Deleted account')?></td><td><?=e(date('j M Y',strtotime($s['created_at'])))?></td><?php endif;?><td><?=e($s['director']?:'—')?></td><td><?=e(ucfirst($s['status']))?></td><?php if(in_array($role,['system_admin','sub_admin','admin'],true)):?><td class="school-actions"><a class="button" href="school_analyze.php?id=<?=$s['id']?>">Analyze</a></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div></main></div><script>const directorSelect=document.querySelector("#director"),directorFields=document.querySelector("#new-director-fields");function toggleNewDirector(){const show=directorSelect?.value==="new";if(directorFields)directorFields.hidden=!show;directorFields?.querySelectorAll("input").forEach(input=>input.required=show)}directorSelect?.addEventListener("change",toggleNewDirector);toggleNewDirector();</script></body></html>

